SET BAIL ON;
SET AUTODDL OFF;





















































COMMIT;

SELECT COUNT(*) AS PACIENTES_LOTE FROM PACIENTES WHERE PAC_EMAIL LIKE 'paciente.teste.%@example.test';
SELECT COUNT(*) AS AGENDAMENTOS_LOTE FROM AGENDAMENTOS WHERE AGD_OBSERVACAO STARTING WITH '[CARGA_TESTE_20260824]';
SELECT COUNT(*) AS CONSULTAS_LOTE FROM CONSULTAS WHERE CON_ID BETWEEN 25 AND 74;
SELECT RET_SITUACAO, COUNT(*) AS TOTAL FROM RETORNOS_CONSULTA WHERE RET_ID BETWEEN 4 AND 53 GROUP BY RET_SITUACAO ORDER BY RET_SITUACAO;
SELECT COUNT(*) AS PARCERIAS_LOTE FROM PARCERIAS WHERE PAR_EMAIL LIKE '%@example.test';
QUIT;

